INSERT INTO games (id,title,category,age,score,base_views,release_date,description,review,pros,cons,platforms,image,hue) VALUES
(0,'Silent Hill f (2025)','สยองขวัญ',16,9.4,0,'2026-10-20','เกมสยองขวัญเชิงจิตวิทยา','เกมสยองขวัญที่มีฉากในญี่ปุ่นยุค 1960 ผู้เล่นรับบทเป็นฮินาโกะ สำรวจเมืองที่ถูกปกคลุมด้วยหมอก ไขปริศนา และต่อสู้กับสัตว์ประหลาด',ARRAY['กราฟิกสวย บรรยากาศหลอน','เนื้อเรื่องลึกลับน่าติดตาม','มีปริศนาและฉากต่อสู้']::text[],ARRAY['ระบบต่อสู้ค่อนข้างยาก','ปริศนาบางจุดซับซ้อน','มีภาพสยองขวัญและความรุนแรง']::text[],'PS5 · PC','images/header.jpg',15),
(1,'Call of Duty: Modern Warfare 4','ต่อสู้',18,9.2,0,'2026-10-12','เกมยิงมุมมองบุคคลที่หนึ่ง','เกมยิงมุมมองบุคคลที่หนึ่งที่เน้นการต่อสู้ทางทหาร มีทั้งภารกิจเนื้อเรื่องและโหมดแข่งขันออนไลน์ ผู้เล่นต้องใช้ทักษะการยิง การวางแผน และการทำงานเป็นทีม',ARRAY['การต่อสู้รวดเร็วและตื่นเต้น','มีโหมดให้เลือกเล่นหลากหลาย','เหมาะกับการเล่นกับเพื่อน']::text[],ARRAY['ต้องใช้ทักษะการยิงค่อนข้างสูง','ต้องใช้ทักษะการยิงค่อนข้างสูง','ผู้เล่นใหม่อาจเสียเปรียบผู้เล่นเก่า']::text[],'PC · Xbox','images/MWA_Meta.jpg',62),
(2,'Phantom Blade Zero','RPG',12,8.6,0,'2026-10-05','แอ็กชันที่เน้นการต่อสู้ด้วยดาบในโลกแฟนตาซี','เกมแอ็กชันที่เน้นการต่อสู้ด้วยดาบในโลกแฟนตาซีที่ได้รับแรงบันดาลใจจากศิลปะการต่อสู้แบบจีน ผู้เล่นต้องเรียนรู้จังหวะโจมตี หลบหลีก และรับมือกับศัตรูที่แข็งแกร่ง',ARRAY['ฉากต่อสู้สวยงามและรวดเร็ว','มีเอกลักษณ์ด้านศิลปะและบรรยากาศ','เหมาะสำหรับรีวิวระบบต่อสู้และกราฟิก']::text[],ARRAY['ต้องฝึกฝนจังหวะการต่อสู้','ผู้เล่นที่ชอบเกมสบาย ๆ อาจรู้สึกยาก','ต้องพิจารณาประสิทธิภาพเครื่องที่ใช้เล่น']::text[],'PS5 · PC','images/phantom blade zero.jpg',109),
(3,'Counter-Strike 2','ยิงปืน',7,8.3,0,'2026-09-28','ยิงแข่งขันระหว่างทีมผู้ก่อการร้ายและหน่วยต่อต้านการก่อการร้าย','เกมยิงแข่งขันระหว่างทีมผู้ก่อการร้ายและหน่วยต่อต้านการก่อการร้าย ผู้เล่นต้องใช้อาวุธอย่างแม่นยำ ซื้ออุปกรณ์ให้เหมาะสม และวางแผนร่วมกับทีมเพื่อเอาชนะอีกฝ่าย',ARRAY['เกมเพลย์แข่งขันจริงจัง','ฝึกความแม่นยำและการตัดสินใจ','มีชุมชนผู้เล่นและการแข่งขันขนาดใหญ่']::text[],ARRAY['มือใหม่อาจถูกผู้เล่นเก่ากดดัน','ต้องสื่อสารกับทีมให้ดี','การเล่นแรงก์สูงต้องฝึกฝนมาก']::text[],'PS5 · PC','images/Counter-Strike 2.jpg',156),
(4,'Dota 2','โมบา',12,8.8,0,'2026-09-22','ต่อสู้แบบทีม 5 ต่อ 5','เกมวางแผนต่อสู้แบบทีม 5 ต่อ 5 ผู้เล่นเลือกฮีโร่ที่มีความสามารถแตกต่างกัน เพื่อเก็บทรัพยากร ป้องกันฐาน และทำลาย Ancient ของฝ่ายตรงข้าม',ARRAY['ฮีโร่และกลยุทธ์มีความหลากหลาย','การแข่งขันมีความลึก','เล่นกับเพื่อนเพื่อวางแผนเป็นทีมได้']::text[],ARRAY['ต้องเรียนรู้ฮีโร่และไอเทมจำนวนมาก','เกมหนึ่งอาจใช้เวลานาน','การประสานงานในทีมมีผลต่อชัยชนะมาก']::text[],'PC','images/Dota 2.jpg',203),
(5,'PUBG: BATTLEGROUNDS','ยิงปืน',12,8.1,0,'2026-09-15','เอาชีวิตรอดที่ผู้เล่นกระโดดร่มลงบนแผนที่เพื่อค้นหาอาวุธและอุปกรณ์','เกมเอาชีวิตรอดที่ผู้เล่นกระโดดร่มลงบนแผนที่เพื่อค้นหาอาวุธและอุปกรณ์ ต่อสู้กับฝ่ายอื่น และเอาตัวรอดในพื้นที่ปลอดภัยที่เล็กลงเรื่อย ๆ',ARRAY['การวางแผนและเอาตัวรอดสนุก','มีอาวุธและรูปแบบการเล่นหลากหลาย','เล่นเป็นทีมกับเพื่อนได้']::text[],ARRAY['อาจต้องรอคิวหรือใช้เวลาเดินทางในเกม','ถูกกำจัดเร็วอาจทำให้เสียอารมณ์','ต้องอาศัยทั้งทักษะและการตัดสินใจ']::text[],'PC · มือถือ','images/PUBG.jpg',250),
(6,'Delta Force','ยิงปืน',12,8.9,0,'2026-09-08','เกมยิงแนวทหารที่เน้นการต่อสู้เป็นทีม','เกมยิงแนวทหารที่เน้นการต่อสู้เป็นทีม มีรูปแบบการเล่นที่เน้นการเข้ายึดพื้นที่ การใช้อุปกรณ์ทางยุทธวิธี และการทำภารกิจให้สำเร็จ',ARRAY['มีรูปแบบการต่อสู้ให้เลือก','เน้นการทำงานเป็นทีม','เหมาะสำหรับคนชอบเกมยิงแนวทหาร']::text[],ARRAY['ต้องทำความเข้าใจอุปกรณ์และระบบเกม','อาจต้องใช้เครื่องที่มีประสิทธิภาพเหมาะสม','ผู้เล่นใหม่ต้องฝึกการเคลื่อนที่และการเล็ง']::text[],'PC','images/Delta Force.jpg',297),
(7,'Apex Legends','ยิงปืน',12,7.9,0,'2026-08-30','เกมยิง Battle Royale ที่ผู้เล่นเลือกตัวละครซึ่งมีความสามารถเฉพาะตัว','เกมยิง Battle Royale ที่ผู้เล่นเลือกตัวละครซึ่งมีความสามารถเฉพาะตัว แล้วร่วมทีมเพื่อเอาชีวิตรอดจากทีมอื่น โดยเน้นการเคลื่อนที่และการใช้ความสามารถให้เหมาะกับสถานการณ์',ARRAY['ระบบเคลื่อนที่รวดเร็วและลื่นไหล','ตัวละครแต่ละตัวมีบทบาทต่างกัน','ต้องใช้กลยุทธ์และการสื่อสาร']::text[],ARRAY['ต้องใช้เวลาเรียนรู้ตัวละคร','การแข่งขันอาจเข้มข้นสำหรับมือใหม่','ต้องฝึกเล็งและเคลื่อนที่ควบคู่กัน']::text[],'PC','images/Apex Legends.jpg',344),
(8,'Cyberpunk 2077','แอคชัน',18,7.6,0,'2026-08-21','เกมสวมบทบาทโลกเปิดที่พาผู้เล่นเข้าสู่ Night City','เกมสวมบทบาทโลกเปิดที่พาผู้เล่นเข้าสู่ Night City เมืองแห่งเทคโนโลยีและอาชญากรรม ผู้เล่นทำภารกิจ สำรวจเมือง ปรับแต่งตัวละคร และเลือกแนวทางในการต่อสู้ได้หลายรูปแบบ',ARRAY['โลกของเกมมีรายละเอียดสูง','เนื้อเรื่องและตัวละครน่าติดตาม','ปรับรูปแบบการต่อสู้ได้หลากหลาย']::text[],ARRAY['เนื้อหาและภารกิจมีจำนวนมาก','ต้องใช้เวลาเล่นค่อนข้างนาน','ต้องตรวจสอบสเปกเครื่องก่อนเล่น']::text[],'PS5 · PC','images/Cyberpunk 2077.jpg',31),
(9,'Fortnite','ผจญภัย',3,8.0,0,'2026-08-14','เกมต่อสู้เอาชีวิตรอดที่มีเอกลักษณ์จากการสร้างสิ่งก่อสร้างและการใช้อาวุธ','เกมต่อสู้เอาชีวิตรอดที่มีเอกลักษณ์จากการสร้างสิ่งก่อสร้างและการใช้อาวุธ นอกจาก Battle Royale ยังมีประสบการณ์การเล่นรูปแบบอื่นที่ผู้เล่นสร้างหรือเข้าไปเล่นกับเพื่อนได้',ARRAY['รูปแบบเกมมีความหลากหลาย','มีระบบเล่นร่วมกับเพื่อน','- มีการอัปเดตและกิจกรรมเป็นระยะ']::text[],ARRAY['ต้องฝึกทักษะการสร้างในบางโหมด','รูปแบบการเล่นเปลี่ยนตามการอัปเดต','อาจมีไอเทมตกแต่งที่ต้องซื้อเพิ่ม']::text[],'Switch','images/Fortnite.jpg',78),
(10,'Minecraft','RPG',16,9.0,0,'2026-08-02','เกมโลกเปิดที่ให้ผู้เล่นขุดทรัพยากร สร้างบ้าน ประดิษฐ์อุปกรณ์ และสำรวจโลกได้อย่างอิสระ','เกมโลกเปิดที่ให้ผู้เล่นขุดทรัพยากร สร้างบ้าน ประดิษฐ์อุปกรณ์ และสำรวจโลกได้อย่างอิสระ สามารถเล่นเอาชีวิตรอดหรือสร้างสิ่งต่าง ๆ โดยไม่จำกัดรูปแบบมากนัก',ARRAY['ให้อิสระในการสร้างสรรค์สูง','เล่นได้ทั้งคนเดียวและกับเพื่อน','มีม็อดและแผนที่จากชุมชนจำนวนมาก']::text[],ARRAY['ผู้เล่นใหม่อาจไม่รู้ว่าจะเริ่มจากตรงไหน','ภาพแบบบล็อกอาจไม่ถูกใจทุกคน','บางม็อดหรือเซิร์ฟเวอร์ต้องตั้งค่าเพิ่มเติม']::text[],'PC · PS5','images/Minecraft.jpg',125),
(11,'Forza Horizon 6','แข่งรถ',3,7.4,0,'2026-07-18','เกมแข่งรถโลกเปิดที่มีฉากในประเทศญี่ปุ่น','เกมแข่งรถโลกเปิดที่มีฉากในประเทศญี่ปุ่น ผู้เล่นสามารถขับรถสำรวจเมือง แข่งขันบนถนนและภูเขา รวมถึงแต่งรถได้อย่างอิสระ',ARRAY['กราฟิกสวยงามและสมจริง','มีรถให้เลือกหลากหลาย','โลกเปิดกว้าง สำรวจได้อิสระ']::text[],ARRAY['ต้องใช้คอมพิวเตอร์สเปกเหมาะสม','บางการแข่งขันมีรูปแบบซ้ำกัน','เน้นการเล่นออนไลน์บางกิจกรรม']::text[],'Xbox · PC','images/Forza Horizon 6.jpg',172)
